import { calculateChakras } from './matrix-calculator';
import { reduceNumber } from './matrix-calculator';

export function getEnergyForAge(age, chakras) {
    const energyMap = [
        // round numbers
        { minAge: 5, maxAge: 5, energy: reduceNumber(chakras.a + chakras.l) }, // a + l

        { minAge: 15, maxAge: 15, energy: reduceNumber(chakras.l + chakras.b) }, // l + b

        { minAge: 25, maxAge: 25, energy: reduceNumber(chakras.b + chakras.b_c) }, // b + b_c

        { minAge: 35, maxAge: 35, energy: reduceNumber(chakras.b_c + chakras.c) }, // b_c + c 

        { minAge: 45, maxAge: 45, energy: reduceNumber(chakras.c + chakras.c_d) }, // c + c_d
        
        { minAge: 55, maxAge: 55, energy: reduceNumber(chakras.c_d + chakras.d) }, // c_d + d
        
        { minAge: 65, maxAge: 65, energy: reduceNumber(chakras.d + chakras.a_d) }, // d + a_d
        
        { minAge: 75, maxAge: 75, energy: reduceNumber(chakras.a_d + chakras.a) }, // a_d + a


    // 0-10
        // 0 лет (a)
        { minAge: 0, maxAge: 0, energy: chakras.a },

        // 1-2: 0 лет + 2-3 года
        { minAge: 1, maxAge: 2, energy: reduceNumber(chakras.a + reduceNumber(chakras.a + chakras.l)) },
        // 2-3: 0 лет + 5 лет
        { minAge: 2, maxAge: 3, energy: reduceNumber(chakras.a + chakras.l) },
        // 3-4: 2-3 года + 5 лет
        { minAge: 3, maxAge: 4, energy: reduceNumber(reduceNumber(chakras.a + chakras.l) + chakras.l) },
        // 5: a + f
        { minAge: 5, maxAge: 5, energy: reduceNumber(chakras.a + chakras.l) },
        // 6-7: 5 лет + 7-8 лет
        { minAge: 6, maxAge: 7, energy: reduceNumber(chakras.l + reduceNumber(chakras.l + chakras.l)) },
        // 7-8: 10 лет + 5 лет
        { minAge: 7, maxAge: 8, energy: reduceNumber(reduceNumber(chakras.l + chakras.l) + chakras.l) },
        // 8-9: 7-8 лет + 10 лет
        { minAge: 8, maxAge: 9, energy: reduceNumber(reduceNumber(chakras.l + chakras.l) + reduceNumber(chakras.l + chakras.l)) },
        // 10: f = (a + b)

    // 11-20
        { minAge: 10, maxAge: 10, energy: reduceNumber(chakras.l) },
        // 11-12: 10 лет + 12-13 лет
        { minAge: 11, maxAge: 12, energy: reduceNumber(chakras.l + reduceNumber(chakras.l + chakras.b)) },
        // 12-13: 10 лет + 15 лет
        { minAge: 12, maxAge: 13, energy: reduceNumber(chakras.l + chakras.b) },
        // 13-14: 12-13 лет + 15 лет
        { minAge: 13, maxAge: 14, energy: reduceNumber(reduceNumber(chakras.l + chakras.b) + chakras.b) },
        // 15: f + b
        { minAge: 15, maxAge: 15, energy: reduceNumber(chakras.l + chakras.b) },
        // 16-17: 15 лет + 17-18 лет
        { minAge: 16, maxAge: 17, energy: reduceNumber(chakras.b + reduceNumber(chakras.b + chakras.b_c)) },
        // 17-18: 15 лет + 20 лет
        { minAge: 17, maxAge: 18, energy: reduceNumber(chakras.b + chakras.b_c) },
        // 18-19: 17-18 лет + 20 лет
        { minAge: 18, maxAge: 19, energy: reduceNumber(reduceNumber(chakras.b + chakras.b_c) + chakras.b_c) },
        // 20: b
        { minAge: 20, maxAge: 20, energy: chakras.b },

    // 21-30
        // 21-22: 20 лет + 22-23 года
        { minAge: 21, maxAge: 22, energy: reduceNumber(chakras.b + reduceNumber(chakras.b + chakras.b_c)) },
        // 22-23: 20 лет + 25 лет
        { minAge: 22, maxAge: 23, energy: reduceNumber(chakras.b + chakras.b_c) },
        // 23-24: 22-23 года + 25 лет
        { minAge: 23, maxAge: 24, energy: reduceNumber(reduceNumber(chakras.b + chakras.b_c) + chakras.b_c) },
        // 25: b + g
        { minAge: 25, maxAge: 25, energy: reduceNumber(chakras.b + chakras.b_c) },
        // 26-27: 25 лет + 27-28 лет
        { minAge: 26, maxAge: 27, energy: reduceNumber(chakras.b_c + reduceNumber(chakras.b_c + chakras.c)) },
        // 27-28: 25 лет + 30 лет
        { minAge: 27, maxAge: 28, energy: reduceNumber(chakras.b_c + chakras.c) },
        // 28-29: 27-28 лет + 30 лет
        { minAge: 28, maxAge: 29, energy: reduceNumber(reduceNumber(chakras.b_c + chakras.c) + chakras.c) },
        // 30: g = (b + c)
        { minAge: 30, maxAge: 30, energy: chakras.b_c },

    // 31-40
        // 31-32: 30 лет + 32-33 года
        { minAge: 31, maxAge: 32, energy: reduceNumber(chakras.b_c + reduceNumber(chakras.b_c + chakras.c)) },
        // 32-33: 30 лет + 35 лет
        { minAge: 32, maxAge: 33, energy: reduceNumber(chakras.b_c + chakras.c) },
        // 33-34: 32-33 года + 35 лет
        { minAge: 33, maxAge: 34, energy: reduceNumber(reduceNumber(chakras.b_c + chakras.c) + chakras.c) },
        // 35: g + c
        { minAge: 35, maxAge: 35, energy: reduceNumber(chakras.b_c + chakras.c) },
        // 36-37: 35 лет + 37-38 лет
        { minAge: 36, maxAge: 37, energy: reduceNumber(chakras.c + reduceNumber(chakras.c + chakras.c_d)) },
        // 37-38: 35 лет + 40 лет
        { minAge: 37, maxAge: 38, energy: reduceNumber(chakras.c + chakras.c_d) },
        // 38-39: 37-38 лет + 40 лет
        { minAge: 38, maxAge: 39, energy: reduceNumber(reduceNumber(chakras.c + chakras.c_d) + chakras.c_d) },
        // 40: c
        { minAge: 40, maxAge: 40, energy: chakras.c },

    // 41-50
        // 41-42: 40 лет + 42-43 года
        { minAge: 41, maxAge: 42, energy: reduceNumber(chakras.c + reduceNumber(chakras.c + chakras.c_d)) },
        // 42-43: 40 лет + 45 лет
        { minAge: 42, maxAge: 43, energy: reduceNumber(chakras.c + chakras.c_d) },
        // 43-44: 42-43 года + 45 лет
        { minAge: 43, maxAge: 44, energy: reduceNumber(reduceNumber(chakras.c + chakras.c_d) + chakras.c_d) },
        // 45: c + y
        { minAge: 45, maxAge: 45, energy: reduceNumber(chakras.c + chakras.c_d) },
        // 46-47: 45 лет + 47-48 лет
        { minAge: 46, maxAge: 47, energy: reduceNumber(chakras.c_d + reduceNumber(chakras.c_d + chakras.d)) },
        // 47-48: 45 лет + 50 лет
        { minAge: 47, maxAge: 48, energy: reduceNumber(chakras.c_d + chakras.d) },
        // 48-49: 47-48 лет + 50 лет
        { minAge: 48, maxAge: 49, energy: reduceNumber(reduceNumber(chakras.c_d + chakras.d) + chakras.d) },
        // 50: y = (c + d)
        { minAge: 50, maxAge: 50, energy: chakras.c_d },
        // 51-52: 50 лет + 52-53 года
        { minAge: 51, maxAge: 52, energy: reduceNumber(chakras.c_d + reduceNumber(chakras.c_d + chakras.d)) },
        // 52-53: 50 лет + 55 лет
        { minAge: 52, maxAge: 53, energy: reduceNumber(chakras.c_d + chakras.d) },
        // 53-54: 52-53 года + 55 лет
        { minAge: 53, maxAge: 54, energy: reduceNumber(reduceNumber(chakras.c_d + chakras.d) + chakras.d) },
        // 55: y + d
        { minAge: 55, maxAge: 55, energy: reduceNumber(chakras.c_d + chakras.d) },
        // 56-57: 55 лет + 57-58 лет
        { minAge: 56, maxAge: 57, energy: reduceNumber(chakras.d + reduceNumber(chakras.d + chakras.a_d)) },
        // 57-58: 55 лет + 60 лет
        { minAge: 57, maxAge: 58, energy: reduceNumber(chakras.d + chakras.a_d) },
        // 58-59: 57-58 лет + 60 лет
        { minAge: 58, maxAge: 59, energy: reduceNumber(reduceNumber(chakras.d + chakras.a_d) + chakras.a_d) },
        // 60: d
        { minAge: 60, maxAge: 60, energy: chakras.d },

    // 61-70
        // 61-62: 60 лет + 62-63 года
        { minAge: 61, maxAge: 62, energy: reduceNumber(chakras.d + reduceNumber(chakras.d + chakras.a_d)) },
        // 62-63: 60 лет + 65 лет
        { minAge: 62, maxAge: 63, energy: reduceNumber(chakras.d + chakras.a_d) },
        // 63-64: 62-63 года + 65 лет
        { minAge: 63, maxAge: 64, energy: reduceNumber(reduceNumber(chakras.d + chakras.a_d) + chakras.a_d) },
        // 65: d + k
        { minAge: 65, maxAge: 65, energy: reduceNumber(chakras.d + chakras.a_d) },
        // 66-67: 65 лет + 67-68 лет
        { minAge: 66, maxAge: 67, energy: reduceNumber(chakras.a_d + reduceNumber(chakras.a_d + chakras.a)) },
        // 67-68: 65 лет + 70 лет
        { minAge: 67, maxAge: 68, energy: reduceNumber(chakras.a_d + chakras.a) },
        // 68-69: 67-68 лет + 70 лет
        { minAge: 68, maxAge: 69, energy: reduceNumber(reduceNumber(chakras.a_d + chakras.a) + chakras.a) },
        // 70: k = (d + a)
        { minAge: 70, maxAge: 70, energy: chakras.a_d },

    // 71-80
        // 71-72: 70 лет + 72-73 года
        { minAge: 71, maxAge: 72, energy: reduceNumber(chakras.a_d + reduceNumber(chakras.a_d + chakras.a)) },
        // 72-73: 70 лет + 75 лет
        { minAge: 72, maxAge: 73, energy: reduceNumber(chakras.a_d + chakras.a) },
        // 73-74: 72-73 года + 75 лет
        { minAge: 73, maxAge: 74, energy: reduceNumber(reduceNumber(chakras.a_d + chakras.a) + chakras.a) },
        // 75: k + a
        { minAge: 75, maxAge: 75, energy: reduceNumber(chakras.a_d + chakras.a) },
        // 76-77: 75 лет + 77-78 лет
        { minAge: 76, maxAge: 77, energy: reduceNumber(chakras.a + reduceNumber(chakras.a + chakras.a)) },
        // 77-78: 75 лет + 80 лет
        { minAge: 77, maxAge: 78, energy: reduceNumber(chakras.a + chakras.a) },
        // 78-79: 77-78 лет + 80 лет
        { minAge: 78, maxAge: 79, energy: reduceNumber(reduceNumber(chakras.a + chakras.a) + chakras.a) },
    ];

    const energyEntry = energyMap.find(entry => age >= entry.minAge && age <= entry.maxAge);
    return energyEntry ? energyEntry.energy : '';
}


